root.command:

IF OBJECT_ID(N'dbo.ContactDeliverToAddressTbl', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.ContactDeliverToAddressTbl', N'CellNumber') IS NULL
    ALTER TABLE dbo.ContactDeliverToAddressTbl ADD CellNumber NVARCHAR(30) NULL;


IF OBJECT_ID(N'dbo.ContactDeliverToAddressTbl', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.ContactDeliverToAddressTbl', N'PhoneNumber') IS NULL
    ALTER TABLE dbo.ContactDeliverToAddressTbl ADD PhoneNumber NVARCHAR(30) NULL;
